    @SuppressWarnings({"unchecked","rawtypes"}) public static <T> int binarySearch(T[] a,int from,int to,T key,Comparator<? super T> c){check(a.length,from,to);int lo=from,hi=to-1;while(lo<=hi){int mid=(lo+hi)>>>1;int r=c==null?((Comparable)a[mid]).compareTo(key):c.compare(a[mid],key);if(r<0)lo=mid+1;else if(r>0)hi=mid-1;else return mid;}return -(lo+1);}
