    /** Fixed-size list writing through to its array (Arrays.asList). */
    static final class FixedList<E> extends AbstractList<E> implements RandomAccess {
        private final E[] a;
        FixedList(E[] a){this.a=Objects.requireNonNull(a);}
        public int size(){return a.length;}
        public E get(int i){return a[i];}
        public E set(int i,E v){E old=a[i];a[i]=v;return old;}
        public int indexOf(Object o){for(int i=0;i<a.length;i++)if(Objects.equals(o,a[i]))return i;return -1;}
        public boolean contains(Object o){return indexOf(o)>=0;}
        public Object[] toArray(){Object[] r=new Object[a.length];System.arraycopy(a,0,r,0,a.length);return r;}
        public void sort(Comparator<? super E> c){Arrays.sort(a,c);}
    }
